From 94210857f6be61f6927a7c94646e43a3daf102f9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:47:02 +0100
Subject: [PATCH] notifications: add option to not show popups for application
 jobs

File operations always popped up when they started and finished, and the
only way to stop that was hiding them from the applet too. A new "Show
popups" setting starts jobs hidden in history, raising them only on error.

BUG: 425355
---
 kcms/notifications/ui/main.qml               | 17 +++++++++++++++++
 libnotificationmanager/job_p.cpp             |  2 --
 libnotificationmanager/jobsmodel_p.cpp       |  7 +++++++
 libnotificationmanager/kcfg/jobsettings.kcfg |  3 +++
 libnotificationmanager/settings.cpp          | 14 ++++++++++++++
 libnotificationmanager/settings.h            |  8 ++++++++
 6 files changed, 49 insertions(+), 2 deletions(-)

diff --git a/kcms/notifications/ui/main.qml b/kcms/notifications/ui/main.qml
index 83dc77275c..8cc7deb330 100644
--- a/kcms/notifications/ui/main.qml
+++ b/kcms/notifications/ui/main.qml
@@ -332,6 +332,23 @@ KCM.SimpleKCM {
             }
         }

+        RowLayout { // just for indentation
+            QtControls.CheckBox {
+                id: applicationJobPopupsCheck
+                Layout.leftMargin: mirrored ? 0 : indicator.width
+                Layout.rightMargin: mirrored ? indicator.width : 0
+                text: i18nc("Show a popup when an application job starts or finishes; failed jobs always show one", "Show popups")
+                checked: kcm.jobSettings.popups
+                onClicked: kcm.jobSettings.popups = checked
+
+                KCM.SettingStateBinding {
+                    configObject: kcm.jobSettings
+                    settingName: "Popups"
+                    extraEnabledConditions: applicationJobsEnabledCheck.checked
+                }
+            }
+        }
+
         RowLayout { // just for indentation
             QtControls.CheckBox {
                 Layout.leftMargin: mirrored ? 0 : indicator.width
diff --git a/libnotificationmanager/job_p.cpp b/libnotificationmanager/job_p.cpp
index 87c685401a..4f91d44648 100644
--- a/libnotificationmanager/job_p.cpp
+++ b/libnotificationmanager/job_p.cpp
@@ -382,8 +382,6 @@ void JobPrivate::finish()
     Job *job = static_cast<Job *>(parent());
     // update timestamp
     job->resetUpdated();
-    // when it was hidden in history, bring it up again
-    job->setDismissed(false);
 }

 // JobViewV2
diff --git a/libnotificationmanager/jobsmodel_p.cpp b/libnotificationmanager/jobsmodel_p.cpp
index 44bc9696aa..e843b13e34 100644
--- a/libnotificationmanager/jobsmodel_p.cpp
+++ b/libnotificationmanager/jobsmodel_p.cpp
@@ -284,6 +284,9 @@ QDBusObjectPath JobsModelPrivate::requestView(const QString &desktopEntry, int c
         }
     }

+    // Without job popups, the job starts out hidden in history
+    job->setDismissed(!m_settings->jobPopups());
+
     job->setSuspendable(capabilities & KJob::Suspendable);
     job->setKillable(capabilities & KJob::Killable);

@@ -346,6 +349,10 @@ QDBusObjectPath JobsModelPrivate::requestView(const QString &desktopEntry, int c
         scheduleUpdate(job, Notifications::DismissableRole);

         if (job->state() == Notifications::JobStateStopped) {
+            // When it was hidden in history, bring it up again, unless job popups are disabled and it succeeded
+            if (m_settings->jobPopups() || job->error()) {
+                job->setDismissed(false);
+            }
             unwatchJob(job);
             updateApplicationPercentage(job->desktopEntry());
             emitJobUrlsChanged();
diff --git a/libnotificationmanager/kcfg/jobsettings.kcfg b/libnotificationmanager/kcfg/jobsettings.kcfg
index af8bcd299f..1363b743af 100644
--- a/libnotificationmanager/kcfg/jobsettings.kcfg
+++ b/libnotificationmanager/kcfg/jobsettings.kcfg
@@ -9,6 +9,9 @@
         <entry name="InNotifications" type="Bool">
             <default>true</default>
         </entry>
+        <entry name="Popups" type="Bool">
+            <default>true</default>
+        </entry>
         <entry name="PermanentPopups" type="Bool">
             <default>true</default>
         </entry>
diff --git a/libnotificationmanager/settings.cpp b/libnotificationmanager/settings.cpp
index 9e0da288ab..53b1ccce38 100644
--- a/libnotificationmanager/settings.cpp
+++ b/libnotificationmanager/settings.cpp
@@ -455,6 +455,20 @@ void Settings::setJobsInNotifications(bool enable)
     d->setDirty(true);
 }

+bool Settings::jobPopups() const
+{
+    return d->jobSettings.popups();
+}
+
+void Settings::setJobPopups(bool enable)
+{
+    if (jobPopups() == enable) {
+        return;
+    }
+    d->jobSettings.setPopups(enable);
+    d->setDirty(true);
+}
+
 bool Settings::permanentJobPopups() const
 {
     return d->jobSettings.permanentPopups();
diff --git a/libnotificationmanager/settings.h b/libnotificationmanager/settings.h
index 82eb89d055..d60a0aa448 100644
--- a/libnotificationmanager/settings.h
+++ b/libnotificationmanager/settings.h
@@ -71,6 +71,11 @@ class NOTIFICATIONMANAGER_EXPORT Settings : public QObject
      * Whether to show application jobs as notifications
      */
     Q_PROPERTY(bool jobsInNotifications READ jobsInNotifications WRITE setJobsInNotifications /*RESET resetJobsPopup*/ NOTIFY settingsChanged)
+    /**
+     * Whether to show a popup when an application job starts or finishes successfully.
+     * Failed jobs always show a popup.
+     */
+    Q_PROPERTY(bool jobPopups READ jobPopups WRITE setJobPopups NOTIFY settingsChanged)
     /**
      * Whether application jobs stay visible for the whole duration of the job
      */
@@ -290,6 +295,9 @@ public:
     bool jobsInNotifications() const;
     void setJobsInNotifications(bool enable);

+    bool jobPopups() const;
+    void setJobPopups(bool enable);
+
     bool permanentJobPopups() const;
     void setPermanentJobPopups(bool enable);

-- 
2.53.0
